import kotlinx.coroutines.*
import kotlinx.coroutines.channels.*

// Capacity is a type-level decision:
val rendezvous = Channel<Job>(Channel.RENDEZVOUS)   // capacity 0: sender and receiver meet
val bounded   = Channel<Job>(256)                  // bounded: send suspends when full -> backpressure
val conflated = Channel<Price>(Channel.CONFLATED)   // keeps only the LATEST (drop-oldest)
val drop      = Channel<Event>(capacity = 64, onBufferOverflow = BufferOverflow.DROP_OLDEST)

// onUndeliveredElement releases a resource that was sent but never delivered:
val resources = Channel<Resource>(onUndeliveredElement = { it.close() })

suspend fun producer() {
    for (j in jobs) bounded.send(j)      // SUSPENDS when full (never blocks a thread)
    bounded.close()                      // the producer closes; receivers drain then throw
}

// select: multiplex with a default (trySend) or a timeout.
select {
    bounded.onReceive { process(it) }
    timeout.onTimeout { }                 // kotlinx: onTimeout
}
